VALUES (4513, 'tt0389722', NULL, '30 Days of Night', '30 Days of Night', 'movie', 2007, 'https://image.tmdb.org/t/p/w500/7LwSrvFA0gz1KAlcrGcinoQPene.jpg', 'https://image.tmdb.org/t/p/original/w8VDpCcKezdBbXJEWMHwttI35mU.jpg', 'This is the story of an isolated Alaskan town that is plunged into darkness for a month each year when the sun sinks below the horizon. As the last rays of light fade, the town is attacked by a bloodthirsty gang of vampires bent on an uninterrupted orgy of destruction. Only the small town''s husband-and-wife Sheriff team stand between the survivors and certain destruction.', NULL, NULL, 7.9726, 6.439, 0, 4.59170454545454589e+01, '2026-07-15 12:01:52', '2026-10-11 05:59:18')
