VALUES (21588, 'tt0109592', NULL, 'Cemetery Man', 'DellaMorte DellAmore', 'movie', 1994, 'https://image.tmdb.org/t/p/w500/cI5AV3jCuxmoQp0N7Z16SI2b7Xk.jpg', 'https://image.tmdb.org/t/p/original/fHPTQ18tuwtJ3JvrCeZMZs4X58Q.jpg', 'Francesco Dellamorte  is the groundskeeper at a cemetery where the dead just won’t stay dead—and it’s up to him to deal with those who come back to life with a hunger for human flesh. But Dellamorte’s job soon becomes much more complicated when he falls for an enigmatic young woman whose husband has recently died.', NULL, NULL, 2.0129, 6.901, 0, 1.66914285714285703e+01, '2026-07-15 12:01:52', '2026-10-11 05:59:18')
