VALUES (27274, 'tt0099611', NULL, 'Frankenhooker', 'Frankenhooker', 'movie', 1990, 'https://image.tmdb.org/t/p/w500/s8Oubzkc2pPdOdj4D23ljZSKRbg.jpg', 'https://image.tmdb.org/t/p/original/pI56isyuRNOr4fFr0jRlIPnr3wv.jpg', 'A medical school dropout loses his fiancée in a tragic lawnmower incident and decides to bring her back to life. Unfortunately, he was only able to save her head, so he goes to the red light district in the city and lures prostitutes into a hotel room so he can collect body parts to reassemble her.', NULL, NULL, 2.4548, 6.3, 0, 1.89606666666666683e+01, '2026-07-15 12:01:52', '2026-10-11 05:59:18')
