VALUES (33217, 'tt1196141', NULL, 'Diary of a Wimpy Kid', 'Diary of a Wimpy Kid', 'movie', 2010, 'https://image.tmdb.org/t/p/w500/iLAGiPnSuODt9cn332bkFElrRig.jpg', 'https://image.tmdb.org/t/p/original/hCjoIDVSxR2j1qEXKso385v9JgS.jpg', 'Greg Heffley is headed for big things, but first he has to survive the scariest, most humiliating experience of any kid’s life – middle school! That won’t be easy, considering he’s surrounded by hairy-freckled morons, wedgie-loving bullies and a moldy slice of cheese with nuclear cooties!', NULL, NULL, 7.1612, 6.286, 0, 8.636, '2026-07-31 03:33:23', '2026-10-11 05:59:18')
