VALUES (136797, 'tt2369135', NULL, 'Need for Speed', 'Need for Speed', 'movie', 2014, 'https://image.tmdb.org/t/p/w500/4ktdbrhCnAoDGLW36afjB717Sa.jpg', 'https://image.tmdb.org/t/p/original/syVAWAnY6fTBDDFntHsM8vFjKex.jpg', 'The film revolves around a local street-racer who partners with a rich and arrogant business associate, only to find himself framed by his colleague and sent to prison. After he gets out, he joins a New York-to-Los Angeles race to get revenge. But when the ex-partner learns of the scheme, he puts a massive bounty on the racer''s head, forcing him to run a cross-country gauntlet of illegal racers in all manner of supercharged vehicles.', NULL, NULL, 16.1763, 6.455, 0, 12.416, '2026-08-17 16:08:12', '2026-10-11 05:59:18')
