VALUES (103332, 'tt1839492', NULL, 'Ruby Sparks', 'Ruby Sparks', 'movie', 2012, 'https://image.tmdb.org/t/p/w500/zELurt0GVRkR5X5ymuk7KXUxhC8.jpg', 'https://image.tmdb.org/t/p/original/4EqTcyWfO807ihMzGHequR7x1Co.jpg', 'Calvin is a young novelist who achieved phenomenal success early in his career but is now struggling with his writing – as well as his romantic life. Finally, he makes a breakthrough and creates a character named Ruby who inspires him. When Calvin finds Ruby, in the flesh, sitting on his couch about a week later, he is completely flabbergasted that his words have turned into a living, breathing person.', NULL, NULL, 4.9345, 7.109, 0, 9.885, '2026-08-26 01:43:46', '2026-10-11 05:59:18')
