VALUES (216015, 'tt2322441', NULL, 'Fifty Shades of Grey', 'Fifty Shades of Grey', 'movie', 2015, 'https://image.tmdb.org/t/p/w500/63kGofUkt1Mx0SIL4XI4Z5AoSgt.jpg', 'https://image.tmdb.org/t/p/original/7IGKrY1f1KfwMipx9wZC4NRgIdF.jpg', 'When college senior Anastasia Steele steps in for her sick roommate to interview prominent businessman Christian Grey for their campus paper, little does she realize the path her life will take. Christian, as enigmatic as he is rich and powerful, finds himself strangely drawn to Ana, and she to him. Though sexually inexperienced, Ana plunges headlong into an affair -- and learns that Christian''s true sexual proclivities push the boundaries of pain and pleasure.', NULL, NULL, 21.7653, 5.858, 0, 11.765, '2026-09-17 03:31:35', '2026-10-11 05:59:18')
